From d1d48bcd97a38bad4e8b3980e383532589c4a265 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:59:54 +0100
Subject: [PATCH] editor/ipv4: allow setting the address range of shared
 connections

The address table was disabled for "Shared to other computers", so the
range could not be set and any address set elsewhere was dropped on every
save. Keep the table enabled for Shared, as NetworkManager uses it.

BUG: 422694
---
 libs/editor/settings/ipv4widget.cpp                   | 10 +++++-----
 libs/editorqml/settings/ipv4settings/ipv4settings.cpp |  6 +++---
 2 files changed, 8 insertions(+), 8 deletions(-)

diff --git a/libs/editor/settings/ipv4widget.cpp b/libs/editor/settings/ipv4widget.cpp
index e20e1d579..be219d7d0 100644
--- a/libs/editor/settings/ipv4widget.cpp
+++ b/libs/editor/settings/ipv4widget.cpp
@@ -312,9 +312,9 @@ void IPv4Widget::slotModeComboChanged(int index)
         m_ui->routeMetric->setEnabled(true);
         m_ui->ipv4RequiredCB->setEnabled(true);
         m_ui->btnRoutes->setEnabled(false);
-        m_ui->tableViewAddresses->setEnabled(false);
-        m_ui->btnAdd->setEnabled(false);
-        m_ui->btnRemove->setEnabled(false);
+        m_ui->tableViewAddresses->setEnabled(index == Shared);
+        m_ui->btnAdd->setEnabled(index == Shared);
+        m_ui->btnRemove->setEnabled(index == Shared);
     } else if (index == Disabled) { // Disabled
         m_ui->dnsLabel->setText(i18n("DNS Servers:"));
         m_ui->dns->setEnabled(false);
@@ -510,8 +510,8 @@ void IPv4Widget::slotDnsDomains()

 bool IPv4Widget::isValid() const
 {
-    if (m_ui->method->currentIndex() == Manual) {
-        if (!d->model.rowCount()) {
+    if (m_ui->method->currentIndex() == Manual || m_ui->method->currentIndex() == Shared) {
+        if (!d->model.rowCount() && m_ui->method->currentIndex() == Manual) {
             return false;
         }

diff --git a/libs/editorqml/settings/ipv4settings/ipv4settings.cpp b/libs/editorqml/settings/ipv4settings/ipv4settings.cpp
index f72aff623..9c0877d44 100644
--- a/libs/editorqml/settings/ipv4settings/ipv4settings.cpp
+++ b/libs/editorqml/settings/ipv4settings/ipv4settings.cpp
@@ -246,7 +246,7 @@ bool IPv4Settings::dhcpClientIdEnabled() const

 bool IPv4Settings::addressTableEnabled() const
 {
-    return m_method == Manual;
+    return m_method == Manual || m_method == Shared;
 }

 bool IPv4Settings::routesEnabled() const
@@ -256,9 +256,9 @@ bool IPv4Settings::routesEnabled() const

 bool IPv4Settings::isValid() const
 {
-    if (m_method == Manual) {
+    if (addressTableEnabled()) {
         const QList<IpRouteEntry> addressEntries = m_addressModel->routes();
-        if (addressEntries.isEmpty())
+        if (addressEntries.isEmpty() && m_method == Manual)
             return false;
         for (const IpRouteEntry &e : addressEntries) {
             QHostAddress ip(e.address);
